		private static _runAutoClosingOpenCharType(prevEditOperationType: EditOperationType, config: CursorConfiguration, model: ITextModel, selections: Selection[], ch: string, insertOpenCharacter: boolean, autoClosingPair: StandardAutoClosingPairConditional): EditOperationResult {
			let commands: ICommand[] = [];
			for (let i = 0, len = selections.length; i < len; i++) {
				const selection = selections[i];
				// Avoid inserting duplicate closing characters when the text after the cursor already
				// starts with a suffix of the pair's close sequence. This handles overlapping pairs
				// like '(' ... ')' and '(*' ... '*)' where typing '*' when the next character is ')'
				// should not lead to inserting another ')'.
				let effectiveClose = autoClosingPair.close;
				try {
					const position = selection.getPosition();
					const lineText = model.getLineContent(position.lineNumber);
					const afterText = lineText.substr(position.column - 1, effectiveClose.length);
					let overlap = 0;
					for (let k = Math.min(effectiveClose.length, afterText.length); k >= 1; k--) {
						if (afterText.substr(0, k) === effectiveClose.substr(effectiveClose.length - k)) {
							overlap = k;
							break;
						}
					}
					if (overlap > 0) {
						effectiveClose = effectiveClose.substr(0, effectiveClose.length - overlap);
					}
				} catch (e) {
					// ignore and use full close sequence
				}
				commands[i] = new TypeWithAutoClosingCommand(selection, ch, insertOpenCharacter, effectiveClose);
			}
			return new EditOperationResult(EditOperationType.Typing, commands, {
				shouldPushStackElementBefore: true,
				shouldPushStackElementAfter: false
			});
		}

